import type { Config } from "drizzle-kit";

export default {
  // Both files: auth-schema.ts is generated by the Better Auth CLI, schema.ts
  // is ours. They share a database and must migrate together.
  schema: ["./src/db/schema.ts", "./src/db/auth-schema.ts"],
  out: "./drizzle",
  dialect: "postgresql",
  dbCredentials: {
    /**
     * Migrations run as the OWNER role, which is deliberately not the role the
     * app connects with. The owner bypasses row-level security unless tables
     * are FORCEd, so keeping these separate is what makes the isolation real.
     * See docs/hipaa-compliance.md and scripts/provision-roles.sql.
     */
    url:
      process.env.MIGRATION_DATABASE_URL ?? process.env.DATABASE_URL ?? "",
  },
  strict: true,
  verbose: true,
} satisfies Config;
